"""Render the bounded 13A reference catalogue as a local, self-contained gallery.
No image generation, material preparation, downloads or game changes.
"""
import html
import json
import pathlib
import statistics

out = pathlib.Path('docs/mission-13-evidence')
catalog = json.loads((out / 'catalog.json').read_text())
entries = catalog['entries']
by_id = {r['id']: r for r in entries}
findings = json.loads((out / 'findings.json').read_text())
baseline = json.loads((out / 'baseline.json').read_text())
esc = lambda s: html.escape(str(s), quote=True)

def author(r):
    a = r['author']
    return ', '.join(a.keys()) if isinstance(a, dict) else ', '.join(a) if isinstance(a, list) else a

def reference(r, label=None):
    return f'''<figure><a href="{esc(r['preview']['file'])}"><img loading="lazy" src="{esc(r['preview']['file'])}" alt="{esc(r['materialFamily'] + ' · ' + r['title'])}"></a>
    <figcaption><strong>{esc(label or r['title'])}</strong><br>{esc(r['id'])} · {esc(author(r))}<br><a href="{esc(r['source'])}">Source et titre original</a> · <a href="{esc(r['licenseURL'])}">{esc(r['license'])}</a><br><small>Réduit et réencodé en JPEG ; licence source conservée.</small></figcaption></figure>'''

def current(name):
    r = next(r for r in baseline['results'] if r['id'] == name and r['profile'] == 'balanced')
    return f'''<figure><a href="{r['file']}"><img loading="lazy" src="{r['file']}" alt="Capture réelle Mission 12 · {esc(name)}"></a><figcaption><strong>Jeu actuel · Mission 12</strong><br>{esc(name)} · Équilibré · 960 × 640<br><a href="baseline.json">Caméra, coordonnées et conditions exactes</a></figcaption></figure>'''

comparisons = []
for f in findings['families']:
    comparisons.append(f'''<section id="{f['id']}"><p class="eyebrow">Priorité {f['priority']} · gain espéré {esc(f['expectedGain'])}</p><h2>{esc(f['label'])}</h2>
    <div class="triptych">{reference(by_id[f['photo']], 'Photographie locale de référence')}{current(f['baseline'])}{reference(by_id[f['candidate']], 'Candidate CC0 · diffuse brute')}</div>
    <dl>{''.join(f'<dt>{label}</dt><dd>{esc(f[key])}</dd>' for key,label in [('alreadyWorks','Acquis Mission 12'),('visibleLimit','Écart visible'),('opportunity','Piste pour 13B'),('costRisk','Coût, risque et limites')])}</dl></section>''')
cards = []
for r in entries:
    group = 'photos' if r['kind'] == 'photograph-reference' else 'textures'
    cards.append(f'''<article data-group="{group}">{reference(r)}<p><span class="tag">{esc(r['decision'])}</span></p><p>{esc(r['observation'])}</p><details><summary>Qualité, droits et empreintes</summary><p>{esc(r['confidence'])}</p><p>{esc(r['poitouMatch'])}</p><p>{esc(r['transformationsAllowed'])}</p><p>Usage : {esc(r['usage'])}</p><p>Échelle source en mètres : {esc(r.get('sourceTileMetres', 'non mesurée'))}</p><p>Dimensions consultées : {esc(r['consultedDimensions'])} · {esc(r['format'])}</p><p>SHA-256 ({esc(r['checksumScope'])}) : <code>{r['sha256']}</code></p><p>Aperçu livré : <code>{r['preview']['sha256']}</code></p></details></article>''')
metrics = ''.join(f'''<tr><td>{esc(r['id'])}</td><td>{esc(r['profile'])}</td><td>{statistics.median(s['synchronizedMs'] for s in r['samples']):.1f}</td><td>{max(s['synchronizedMs'] for s in r['samples']):.1f}</td><td>{r['samples'][0]['calls']}</td><td>{r['state']['textures']}</td></tr>''' for r in baseline['results'])
document = '''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Endless Earth · Mission 13A · Matières authentiques</title><link rel="icon" href="data:,">
<style>:root{color-scheme:light;--ink:#273c33;--paper:#f2efe6;--line:#c7c9b7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}header,main,footer{max-width:1440px;margin:auto;padding:32px}header{padding-top:64px}h1,h2{font-family:Georgia,serif;font-weight:400;line-height:1.2}h1{font-size:clamp(2rem,5vw,4.6rem);max-width:1000px}h2{font-size:2rem}a{color:#365f54;overflow-wrap:anywhere}p{max-width:1000px}section{padding:32px 0;border-top:1px solid var(--line)}.eyebrow,.tag{font-size:.78rem;letter-spacing:.04em;text-transform:uppercase}.eyebrow{color:#52695d}.tag{background:#dce1d2;padding:5px 9px;border-radius:12px}.triptych{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}figure{margin:0;min-width:0}img{display:block;width:100%;height:300px;object-fit:contain;background:#e4e0d3}figcaption{padding:12px 0;font-size:.9rem;overflow-wrap:anywhere}small{color:#536255}dl{display:grid;grid-template-columns:170px 1fr;gap:10px 24px;max-width:1100px}dt{font-weight:650}dd{margin:0}.catalog{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}article{padding:16px;background:#fffdf6;border:1px solid var(--line);border-radius:6px;min-width:0}article p{font-size:.9rem}code{overflow-wrap:anywhere;font-size:.75rem}button{font:inherit;border:1px solid #738774;background:transparent;color:var(--ink);padding:8px 14px;border-radius:18px;margin:4px;cursor:pointer}button[aria-pressed=true]{color:#fff;background:#365b49}nav{display:flex;flex-wrap:wrap;gap:16px}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:.9rem}td,th{padding:8px;text-align:left;border-bottom:1px solid var(--line)}[hidden]{display:none!important}.notice{padding:20px;background:#e4e8da;border-left:4px solid #66806b}.baseline{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}@media(max-width:850px){header,main,footer{padding:20px}.triptych,.catalog{grid-template-columns:1fr}.baseline{grid-template-columns:1fr}dl{grid-template-columns:1fr;gap:4px}dd{margin-bottom:16px}img{height:auto;max-height:450px}}</style>
<header><p class="eyebrow">Endless Earth · Jalon 13A · 11 novembre 2026</p><h1>Les matières d’un village vivant</h1><p>38 ressources réellement examinées : 17 vues locales, 21 textures CC0. La pierre irrégulière et les enduits offrent les pistes les plus prometteuses. Les toitures demandent surtout le bon dessin et une variation calme.</p><p class="notice"><strong>Étude uniquement.</strong> Le moteur, les matériaux du jeu et la géographie sont ceux de Mission 12. Les candidates sont présentées comme fichiers de couleur bruts, sans essai d’intégration M13. Toute amélioration évoquée reste à démontrer après votre accord pour 13B.</p><nav><a href="#comparaisons">Planche comparative</a><a href="#catalogue">Catalogue et crédits</a><a href="#reference">Huit vues du jeu actuel</a><a href="#mesures">Mesures et limites</a><a href="../mission-13.md">Rapport</a><a href="catalog.json">Catalogue JSON</a></nav><p><small>Photos de référence distinctes des textures : aucune photographie locale n’est proposée pour fournir des pixels au jeu. Les comparaisons ne sont ni des recalages de caméra ni des mesures d’albédo. Les licences de chaque image figurent sous son aperçu.</small></p></header><main>
<div id="comparaisons">''' + ''.join(comparisons) + '''</div>
<section id="catalogue"><h2>Catalogue consultable</h2><p>Les vues ordinaires complètent les vues patrimoniales. Les ressources rejetées restent visibles pour expliquer les choix. Ouvrir un aperçu pour l’examiner ; les détails contiennent sa provenance et l’empreinte du fichier réellement téléchargé.</p><div role="group" aria-label="Filtrer les références"><button data-filter="all" aria-pressed="true">Toutes · 38</button><button data-filter="photos" aria-pressed="false">Vues locales · 17</button><button data-filter="textures" aria-pressed="false">Textures CC0 · 21</button></div><div class="catalog">''' + ''.join(cards) + '''</div><p><a href="credits.md">Crédits et modifications de chaque image</a> · <a href="license-checks.json">Vérification des licences</a> · <a href="rejected.json">Rejets et difficultés d’accès</a></p></section>
<section id="reference"><h2>Le jeu actuel, sans retouche</h2><p>Huit stations nouvelles depuis main a8ce9c9. Les images ne sont pas générées. La station falaise conserve son obstruction partielle par un bâtiment et les facettes du relief actuel. Les positions d’inspection sont diagnostiques, pas un itinéraire de promenade.</p><div class="baseline">''' + ''.join(current(r['id']) for r in baseline['results'] if r['profile'] == 'balanced') + '''</div><p>Sources géographiques des captures : © IGN / ASP · Licence Ouverte 2.0 ; © contributeurs OpenStreetMap · ODbL. Les textures et créations Mission 12 gardent leurs crédits. <a href="../../public/data/LICENSE.md">Notice complète</a>.</p><p><a href="../mission-08-5-captures/geographic-coverage.jpg">Référence aérienne IGN déjà présente, effectivement examinée</a> : contexte des masses et surfaces ; aucune composition de façade déduite de l’orthophoto.</p></section>
<section id="mesures"><h2>Une référence technique, pas un gain déjà mesuré</h2><p>Chromium 156, SwiftShader, 960 × 640, DPR 1, après-midi clair du 21 juin simulé. Six rendus avec synchronisation et lecture de pixels par ligne : médiane et maximum en ms. Ces valeurs incluent un rendu logiciel et ne mesurent pas une cadence de promenade, un P95 robuste ou un GPU physique.</p><div class="table"><table><thead><tr><th>Vue</th><th>Profil</th><th>Médiane ms</th><th>Maximum ms</th><th>Appels</th><th>Textures</th></tr></thead><tbody>''' + metrics + '''</tbody></table></div><p>Aucune texture ajoutée au jeu : surcoût de rendu et téléchargement des références pendant la marche <strong>nul par construction</strong>, confirmé par les fichiers moteur/public inchangés ; aucun gain de performance M13 revendiqué. Les ressources de cette galerie sont documentaires et restent hors du build Vite du jeu.</p><p>179 tests Node et compilation réussis ; contrôle du build compilé, trois vues, déplacement, son et mobile ; rechargements réels de zone, cache architecture/nature, replis de ressources, profils, météo et cycles audio rejoués. <a href="checks/summary.json">Résultats et limites</a> · <a href="preservation.json">Préservation</a> · <a href="baseline.json">Mesures brutes</a>.</p><p class="notice"><strong>À juger :</strong> l’irrégularité de la pierre, les deux familles d’enduit, la forme des petites tuiles et la discrétion du grain. La prochaine étape peut tester une bibliothèque partagée de dix références, en gardant les témoins procéduraux. <strong>Arrêt après 13A ; attendre votre autorisation explicite pour 13B.</strong></p></section></main><footer><p>Budget : 0 € · Aucun abonnement ni génération IA facturée. Cette galerie sert à la revue locale de la branche ; aucune publication sur le site GitHub Pages principal.</p></footer><script>document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-group]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.group!==button.dataset.filter)}));</script></html>'''
(out / 'index.html').write_text(document)
credits = ['# Mission 13A — Crédits des aperçus', '', 'Chaque image est un fichier indépendant, sous sa licence indiquée. Les aperçus ont uniquement été réduits proportionnellement et réencodés en JPEG ; aucune couleur ni perspective retouchée. Les images CC BY-SA conservent leur licence source et ne sont pas des matériaux du jeu. Ces crédits doivent accompagner leur redistribution.', '']
for r in entries:
    credits += [f"## {r['id']} — {r['title']}", '', f"Auteur : {author(r)}. [Source originale]({r['source']}) · [{r['license']}]({r['licenseURL']}). Vérification : {r['checked']}.", '', f"Fichier : `{r['preview']['file']}`. Modifications : réduction proportionnelle et réencodage JPEG documentaire. Licence conservée : {r['license']}.", '']
(out / 'credits.md').write_text('\n'.join(credits))
print('Gallery:', len(entries), 'entries,', len(comparisons), 'comparisons')
